// EDIT ONLY THIS NON-SECRET ID after importing. The Chatwoot URL, account and token belong
// in the dedicated Chatwoot API credential of @renatoascencio/n8n-nodes-chatwoot@0.9.0.
// NO SEND OPERATIONS are present.
const id='REPLACE_CHATWOOT_CAMPAIGN_DISPLAY_ID';
if(!/^[1-9][0-9]*$/.test(id))throw new Error('CONFIG_REQUIRED: enter an existing numeric Chatwoot campaign display ID');
return [{json:{campaignId:Number(id),readOnly:true}}];

// Only aggregate counts and Meta failure-code frequency leave this workflow.
// Campaign recipient records may contain phone/name/content; do not save executions or pin data.
const metrics=$('Chatwoot - Campaign Get Metrics').first().json;
const entries=$input.all().map(x=>x.json).filter(x=>x&&Object.keys(x).length>0);
const counts={queued:0,skipped:0,sent:0,delivered:0,read:0,failed:0};
const errors={},seen=new Set();
for(const row of entries){
  const id=row?.contact?.id;
  if(!Number.isInteger(id)||id<1||seen.has(id)||!Object.hasOwn(counts,row.status))throw new Error('Invalid or duplicate recipient response; stop reporting');
  seen.add(id);counts[row.status]++;
  if(row.status==='failed'){
    const code=row.error_code===null||row.error_code===undefined?'UNKNOWN':String(row.error_code);
    if(!/^(UNKNOWN|[0-9]{3,8})$/.test(code))throw new Error('Unexpected provider error-code format');
    errors[code]=(errors[code]||0)+1;
  }
}
if(!Number.isInteger(metrics.audience)||metrics.audience!==seen.size||
    metrics.delivered!==counts.delivered+counts.read||metrics.read!==counts.read||
    metrics.failed!==counts.failed||metrics.skipped!==counts.skipped)
 throw new Error('Chatwoot aggregate vs recipient mismatch; could be changing during reads—retry later');
return [{json:{
  checkedAt:new Date().toISOString(),mode:'READ_ONLY',
  chatwootCampaignDisplayId:$('Set Existing Campaign ID - Fail Closed').first().json.campaignId,
  audience:seen.size,counts,deliveredIncludingRead:counts.delivered+counts.read,
  failureCodeCounts:errors,crmEventWriteAuthorized:false,
  evidence:'Chatwoot campaign analytics; Meta message IDs/timestamps not available'
}}];
